from __future__ import annotations

import json
import os
import sqlite3
import threading
from pathlib import Path

from app.models import Note

SCHEMA = (
    """
    CREATE TABLE IF NOT EXISTS notes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        body TEXT NOT NULL,
        tags TEXT NOT NULL DEFAULT '[]'
    )
    """,
)


def get_db_path() -> Path:
    configured = os.getenv("NOTES_DB_PATH")
    if configured:
        return Path(configured)
    return Path(__file__).resolve().parent.parent / "notes.db"


class ConnectionPool:
    """Thread-local SQLite connection pool."""

    def __init__(self, db_path: Path) -> None:
        self._db_path = db_path
        self._local = threading.local()

    def _get_connection(self) -> sqlite3.Connection:
        conn = getattr(self._local, "connection", None)
        if conn is not None:
            try:
                # Check if connection is still valid
                conn.execute("SELECT 1")
                return conn
            except sqlite3.Error:
                # Connection is broken, close it and create a new one
                try:
                    conn.close()
                except sqlite3.Error:
                    pass
                self._local.connection = None
                conn = None

        if conn is None:
            conn = self._create_connection()
            self._local.connection = conn
        return conn

    def _create_connection(self) -> sqlite3.Connection:
        path = self._db_path
        path.parent.mkdir(parents=True, exist_ok=True)
        connection = sqlite3.connect(path)
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA foreign_keys = ON")
        connection.execute("PRAGMA case_sensitive_like = ON")
        for statement in SCHEMA:
            connection.execute(statement)
        connection.commit()
        return connection

    def get_connection(self) -> sqlite3.Connection:
        return self._get_connection()

    def close(self) -> None:
        conn = getattr(self._local, "connection", None)
        if conn is not None:
            try:
                conn.close()
            except sqlite3.Error:
                pass
            self._local.connection = None


# Module-level pool instance
_pool: ConnectionPool | None = None
_pool_lock = threading.Lock()


def _get_pool() -> ConnectionPool:
    global _pool
    if _pool is None:
        with _pool_lock:
            if _pool is None:
                _pool = ConnectionPool(get_db_path())
    return _pool


def initialize_db() -> None:
    pool = _get_pool()
    conn = pool.get_connection()
    # Ensure schema is created
    for statement in SCHEMA:
        conn.execute(statement)
    conn.commit()


def _normalize_tags(tags: list[str]) -> str:
    return json.dumps(sorted({tag.strip() for tag in tags if tag and tag.strip()}))


def _make_note(note_id: int, title: str, body: str, tags: str) -> Note:
    return Note.model_validate({"id": note_id, "title": title, "body": body, "tags": json.loads(tags or "[]")})


def _to_note(row: sqlite3.Row) -> Note:
    return _make_note(row["id"], row["title"], row["body"], row["tags"])


def _row_to_dict(row: sqlite3.Row) -> dict:
    """Convert a sqlite3.Row to a plain dictionary, parsing tags JSON."""
    tags_raw = row["tags"]
    tags = json.loads(tags_raw) if tags_raw else []
    return {
        "id": row["id"],
        "title": row["title"],
        "body": row["body"],
        "tags": tags,
    }


def create_note(title: str, body: str, tags: list[str]) -> Note:
    pool = _get_pool()
    connection = pool.get_connection()
    payload = _normalize_tags(tags)
    cursor = connection.execute(
        "INSERT INTO notes (title, body, tags) VALUES (?, ?, ?)",
        (title, body, payload),
    )
    note_id = cursor.lastrowid
    connection.commit()
    row = connection.execute("SELECT id, title, body, tags FROM notes WHERE id = ?", (note_id,)).fetchone()
    return _to_note(row)


def get_note(note_id: int) -> Note | None:
    pool = _get_pool()
    connection = pool.get_connection()
    row = connection.execute("SELECT id, title, body, tags FROM notes WHERE id = ?", (note_id,)).fetchone()
    if row is None:
        return None
    return _to_note(row)


def list_notes(
    *,
    search_text: str | None = None,
    tags_filter: list[str] | None = None,
    offset: int = 0,
    limit: int = 20,
) -> tuple[list[dict], int]:
    pool = _get_pool()
    connection = pool.get_connection()

    wanted = [tag for tag in tags_filter or [] if tag]

    conditions = []
    params: list[object] = []

    if search_text:
        conditions.append("(title LIKE ? OR body LIKE ?)")
        params.extend([f"%{search_text}%", f"%{search_text}%"])

    if wanted:
        for tag in wanted:
            conditions.append("(tags LIKE ?)")
            params.append(f"%\"{tag}\"%")

    where_clause = " AND ".join(conditions) if conditions else "1=1"

    count_sql = f"SELECT COUNT(*) FROM notes WHERE {where_clause}"
    count_row = connection.execute(count_sql, params).fetchone()
    total = count_row[0]

    query_sql = f"SELECT id, title, body, tags FROM notes WHERE {where_clause} ORDER BY id ASC LIMIT ? OFFSET ?"
    query_params = params + [limit, offset]

    rows = connection.execute(query_sql, query_params).fetchall()

    # Bypass Pydantic validation for read path performance
    items = [_row_to_dict(row) for row in rows]
    return items, total


def update_note(note_id: int, title: str, body: str, tags: list[str]) -> Note | None:
    pool = _get_pool()
    connection = pool.get_connection()
    row = connection.execute("SELECT id, title, body, tags FROM notes WHERE id = ?", (note_id,)).fetchone()
    if row is None:
        return None

    payload = _normalize_tags(tags)
    connection.execute(
        "UPDATE notes SET title = ?, body = ?, tags = ? WHERE id = ?",
        (title, body, payload, note_id),
    )
    connection.commit()

    updated_row = connection.execute("SELECT id, title, body, tags FROM notes WHERE id = ?", (note_id,)).fetchone()
    return _to_note(updated_row)


def delete_note(note_id: int) -> bool:
    pool = _get_pool()
    connection = pool.get_connection()
    cursor = connection.execute("DELETE FROM notes WHERE id = ?", (note_id,))
    connection.commit()
    deleted = cursor.rowcount > 0
    return deleted

from __future__ import annotations

from pathlib import Path

from fastapi import FastAPI, HTTPException, Query, Response, status
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles

from app.db import create_note, delete_note, get_note, initialize_db, list_notes, update_note
from app.models import Note, NoteCreate, NoteUpdate

app = FastAPI(title="Notes API")
initialize_db()
app.mount("/static", StaticFiles(directory=Path(__file__).resolve().parent / "static"), name="static")


@app.on_event("startup")
async def startup_event() -> None:
    initialize_db()


@app.post("/notes", response_model=Note, status_code=status.HTTP_201_CREATED)
def create_note_endpoint(note: NoteCreate) -> Note:
    return create_note(note.title, note.body, note.tags)


@app.get("/notes/{note_id}", response_model=Note)
def read_note(note_id: int) -> Note:
    note = get_note(note_id)
    if note is None:
        raise HTTPException(status_code=404, detail="Note not found")
    return note


@app.get("/notes")
def list_notes_endpoint(
    q: str | None = Query(default=None, description="Substring search over title or body."),
    tag: list[str] = Query(default_factory=list),
    offset: int = Query(default=0, ge=0),
    limit: int = Query(default=20, ge=1, le=100),
) -> dict[str, object]:
    clean_tags = [item.strip() for item in tag if isinstance(item, str) and item.strip()]
    items, total = list_notes(search_text=q, tags_filter=clean_tags, offset=offset, limit=limit)
    return {
        "items": items,
        "total": total,
        "offset": offset,
        "limit": limit,
    }


@app.put("/notes/{note_id}", response_model=Note)
def update_note_endpoint(note_id: int, note: NoteUpdate) -> Note:
    updated = update_note(note_id, note.title, note.body, note.tags)
    if updated is None:
        raise HTTPException(status_code=404, detail="Note not found")
    return updated


@app.delete("/notes/{note_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_note_endpoint(note_id: int) -> Response:
    deleted = delete_note(note_id)
    if not deleted:
        raise HTTPException(status_code=404, detail="Note not found")
    return Response(status_code=204)


@app.get("/", include_in_schema=False)
def read_index() -> FileResponse:
    return FileResponse(Path(__file__).resolve().parent / "static" / "index.html")


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=8000)
